  function drawLevels(pane) {
    let lv = 'prog', ex = 'taxi';
    pane.innerHTML = `<div class="stack">
      <div class="row"><span class="small dim">Пример:</span>${ui.seg('ex', [{ v: 'taxi', t: '🚕 Такси' }, { v: 'iskra', t: '🔧 «Искра Онлайн»' }], ex)}</div>
      <div class="row"><span class="small dim">Понятие:</span>${ui.seg('lv', LEVELS, lv, 'accent')}</div>
      <div class="msw-tiles" data-tl></div>
      <div data-tx></div>
    </div>`;
    function draw() {
      const ks = LV_KINDS[lv];
      TR.$('[data-tl]', pane).innerHTML = TILES[ex].map(x => {
        const on = !ks || ks.includes(x.k);
        return `<div class="msw-tile ${on ? 'on' : 'off'}"><span class="k">${esc(KIND_T[x.k])}</span><span>${esc(x.t)}</span></div>`;
      }).join('');
      const tx = LV_TXT[lv];
      let h = `<div class="stack tight"><p>${tx[ex]}</p><p class="muted">${tx.an}</p></div>`;
      if (lv === 'sys') h += ui.note('info', 'Что здесь важно аналитику', 'Заказчик говорит «приложение», потому что видит только экран. Аналитик уточняет, о какой части системы речь. Иначе в требования и в смету не попадут АРМ мастера, планшет механика, правила BR, хранение данных и связи с 1С и ЮKassa — а работать без них «Искра» не сможет.');
      if (lv === 'svc') h += ui.note('warn', 'Ловушка', 'Программа и сервис не исключают друг друга: сервис записи — тоже программа, просто устроенная так, чтобы отдавать свои функции другим программам. А услуга «ТО» вообще не программа — это то, что продаёт «Искра».');
      TR.$('[data-tx]', pane).innerHTML = h;
    }
    ui.onSeg(pane, (n, v) => { if (n === 'lv') lv = v; if (n === 'ex') ex = v; draw(); });
    draw();
  }
  function drawKinds(pane) {
    pane.innerHTML = `<div class="stack">
      <div class="msw-c3">${APP_KINDS.map(k => `<div class="card"><span class="chip info msw-tag">${esc(k.t)}</span><span class="small">${k.d}</span><span class="small"><b>В «Искре»:</b> ${k.ex}</span><span class="small muted">${k.an}</span></div>`).join('')}</div>
      ${ui.note('info', 'Почему у механика веб, а не мобильное приложение', 'Сергей Петрович просил крупные кнопки и чтобы планшеты не надо было обновлять по одному. Веб-приложение обновляется на сервере сразу для всех цехов, а камера планшета доступна и из браузера. Выбор вида приложения — решение команды с аналитиком: он приносит требования (кто, где, в каких условиях работает).')}
      <div data-game></div>
    </div>`;
    miniGame(TR.$('[data-game]', pane), { title: 'Игра «Какое это приложение?»', items: APP_GAME, kinds: APP_KINDS.map(k => ({ v: k.v, t: k.t })), sum: 'Подсказка: ставили из магазина приложений — мобильное; открыли в браузере — веб, даже если на весь экран; запустили с ярлыка на компьютере — десктопное. Одно и то же приложение может иметь несколько видов: у 1С есть и десктопный, и веб-клиент.' });
  }
  function drawSvc(pane) {
    let s = 'biz';
    pane.innerHTML = `<div class="stack">
      <div class="row"><span class="small dim">Смысл:</span>${ui.seg('sv', [{ v: 'biz', t: 'Для бизнеса: услуга' }, { v: 'it', t: 'Для IT: часть системы' }, { v: 'saas', t: 'SaaS' }], s, 'accent')}</div>
      <div data-sv></div>
      <div data-game></div>
    </div>`;
    const TXT = {
      biz: `<div class="card flat"><div class="msw-def">
        <span class="k">Что это</span><div class="v">Услуга, которую компания продаёт клиенту, и то, как её оказывают. «Сервис» в этом смысле — ТО, шиномонтаж, качество обслуживания.</div>
        <span class="k">В «Искре»</span><div class="v">Запись на ТО, замена масла, сезонная переобувка, хранение машины после «Готов» (BR-13). Из услуг состоит каталог, по которому считается цена «от» (BR-5).</div>
        <span class="k">Что важно аналитику</span><div class="v">Каталог услуг — это данные системы: название, нормо-часы, цена «от». От нормо-часов зависит, сколько слотов займёт запись (BR-1).</div>
      </div></div>`,
      it: `<div class="card flat"><div class="msw-def">
        <span class="k">Что это</span><div class="v">Самостоятельная часть системы, которая отвечает за одно дело и отдаёт свои функции другим программам через API. Сервис можно обновлять, не трогая остальные.</div>
        <span class="k">Наши сервисы</span><div class="v">Бэкенд «Искра Онлайн» разделён на сервисы: записи, заказ-нарядов, уведомлений, платежей, интеграций. Каждый — своя зона правил.</div>
        <span class="k">Чужие сервисы</span><div class="v">ЮKassa (оплата), SMS-шлюз SMSC, push (Firebase Cloud Messaging и APNs), онлайн-касса АТОЛ. Их делают другие компании; мы подключаемся по их API и правилам.</div>
        <span class="k">Что важно аналитику</span><div class="v">Для каждого сервиса — какие функции он отдаёт, кто к нему обращается и что делать, если он не отвечает.</div>
      </div></div>`,
      saas: `<div class="card flat"><div class="msw-def">
        <span class="k">Что это</span><div class="v">Software as a Service — «программа как услуга». Готовое приложение работает у поставщика в интернете, а вы платите подписку и пользуетесь через браузер или API. Ничего не ставите и не обновляете сами.</div>
        <span class="k">Примеры</span><div class="v">Онлайн-касса АТОЛ Онлайн по подписке, Figma у Ники, сервисы email-рассылок, которые хочет Кирилл.</div>
        <span class="k">Что важно аналитику</span><div class="v">Купить SaaS или делать своё — решение с последствиями: SaaS быстрее, но правила у него чужие. Аналитик сравнивает, закрывает ли готовый сервис требования «Искры».</div>
      </div></div>`
    };
    ui.onSeg(pane, (n, v) => { if (n === 'sv') { s = v; TR.$('[data-sv]', pane).innerHTML = TXT[s]; } });
    TR.$('[data-sv]', pane).innerHTML = TXT[s];
    miniGame(TR.$('[data-game]', pane), { title: 'Игра «В каком смысле сервис?»', items: SVC_GAME, kinds: [{ v: 'biz', t: 'Услуга' }, { v: 'it', t: 'IT-сервис' }], sum: 'Если говорят о том, что получает клиент «Искры», — это услуга. Если о программе, к которой обращаются другие программы, — IT-сервис. На встречах с бизнесом аналитик переспрашивает: «Вы имеете в виду услугу или часть системы?»' });
  }

