          ui.seq(TR.$('[data-sq]', pane), { lanes: BOOK_LANES, steps: BOOK_STEPS, laneW: 150, title: 'Путь нажатия «Записаться»', hint: 'Нажмите «Шаг →» или «Проиграть».',
            onEnd() { TR.$('[data-sum]', pane).innerHTML = ui.note('info', 'Итог', 'Это и есть <b>клиент–сервер</b>: клиент спрашивает, сервер решает и отвечает. Фронтенд — шаги 1–2 и 9–10, бэкенд — 3–8 и 11–12, чужой SMS-шлюз — 13. Елена видела только шаги 1 и 10, а аналитик описывает все — особенно то, что будет, если какой-то шаг не случится.'); } });
